    Schedule::whereIn('id', $substituteIds)->update($updates);

    Log::info('reschedule_session.substitute_schedules_synced', [
        'student_class_id' => $classId,
        'original_date' => $originalSessionDate,
        'original_start_time' => $originalStartHm,
        'new_date' => $newDateOnly,
        'new_start_time' => $newStartHm,
        'substitute_ids' => $substituteIds,
    ]);

    // FR-002: After moving substitute rows to the new date, purge any
    // other scheduled rows tied to the same anchor (original_schedule_id)
    // on the new date. This removes duplicates created by the frontend
    // reschedule flow (e.g. SmartCalendar.submitReschedule inserting a
    // payload2 with the original teacher when a substitute row already
    // exists). The updated substitute rows (in $substituteIds) are the
    // source of truth; rows outside that set for the same anchor/date
    // are stale and would otherwise win the MAX(id) tiebreak in
    // ClassSessionController::index and display the wrong teacher.
    if ($newDateOnly) {
        $anchorIds = Schedule::whereIn('id', $substituteIds)
            ->pluck('original_schedule_id')
            ->filter()
            ->unique()
            ->values()
            ->all();
        if (!empty($anchorIds)) {
            $deleteQuery = Schedule::where('student_course_id', $classId)
                ->whereDate('schedule_date', $newDateOnly)
                ->where('status', 'scheduled')
                ->whereIn('original_schedule_id', $anchorIds)
                ->whereNotIn('id', $substituteIds);
            $deletedIds = $deleteQuery->pluck('id')->all();
            if (!empty($deletedIds)) {
                Schedule::whereIn('id', $deletedIds)->delete();
                Log::info('reschedule_session.duplicate_scheduled_rows_deleted', [
                    'student_class_id' => $classId,
                    'new_date' => $newDateOnly,
                    'anchor_ids' => $anchorIds,
                    'deleted_ids' => $deletedIds,
                ]);
            }
        }
    }
}

